Dictionary_String* Dictionary_String_make(void) {
Dictionary_String* dictionary = (Dictionary_String*)SPITE_MALLOC(sizeof(Dictionary_String));
dictionary->header.ref_count = 1;
dictionary->header.class_id = 99;
#ifdef SPITE_DEBUG_MEMORY
spite_debug_register_object(dictionary, 99);
#endif
dictionary->keys = 0;
dictionary->values = 0;
dictionary->count = 0;
dictionary->capacity = 0;
return dictionary;
}
Dictionary_String* Dictionary_String_retain(Dictionary_String* self) {
if (self != 0) self->header.ref_count = self->header.ref_count + 1;
return self;
}
void Dictionary_String_release(Dictionary_String* self) {
if (self == 0) return;
self->header.ref_count = self->header.ref_count - 1;
if (self->header.ref_count > 0) return;
for (int64_t spite_index = 0; spite_index < self->count; spite_index = spite_index + 1) {
SpiteString_release(self->keys[spite_index]);
SpiteString_release(self->values[spite_index]);
}
SPITE_FREE(self->keys);
SPITE_FREE(self->values);
SPITE_FREE(self);
}
int64_t Dictionary_String_index_of_key(Dictionary_String* self, SpiteString* key) {
for (int64_t spite_index = 0; spite_index < self->count; spite_index = spite_index + 1) {
if (SpiteString_equals(self->keys[spite_index], key)) return spite_index;
}
return -1;
}
void Dictionary_String_set(Dictionary_String* self, SpiteString* key, SpiteString* value) {
int64_t existing_index = Dictionary_String_index_of_key(self, key);
if (existing_index >= 0) {
SpiteString_release(self->values[existing_index]);
SpiteString_release(self->keys[existing_index]);
self->keys[existing_index] = key;
self->values[existing_index] = value;
return;
}
if (self->count == self->capacity) {
int64_t new_capacity = self->capacity == 0 ? 4 : self->capacity * 2;
self->keys = (SpiteString**)SPITE_REALLOC(self->keys, (size_t)new_capacity * sizeof(SpiteString*));
self->values = (SpiteString**)SPITE_REALLOC(self->values, (size_t)new_capacity * sizeof(SpiteString*));
self->capacity = new_capacity;
}
self->keys[self->count] = key;
self->values[self->count] = value;
self->count = self->count + 1;
}
SpiteString* Dictionary_String_get(Dictionary_String* self, SpiteString* key) {
int64_t existing_index = Dictionary_String_index_of_key(self, key);
SpiteString_release(key);
if (existing_index < 0) return 0;
return SpiteString_retain(self->values[existing_index]);
}
bool Dictionary_String_has(Dictionary_String* self, SpiteString* key) {
bool spite_found = Dictionary_String_index_of_key(self, key) >= 0;
SpiteString_release(key);
return spite_found;
}
void Dictionary_String_remove(Dictionary_String* self, SpiteString* key) {
int64_t existing_index = Dictionary_String_index_of_key(self, key);
SpiteString_release(key);
if (existing_index < 0) return;
SpiteString_release(self->values[existing_index]);
SpiteString_release(self->keys[existing_index]);
for (int64_t spite_index = existing_index; spite_index < self->count - 1; spite_index = spite_index + 1) {
self->keys[spite_index] = self->keys[spite_index + 1];
self->values[spite_index] = self->values[spite_index + 1];
}
self->count = self->count - 1;
}
int64_t Dictionary_String_count(Dictionary_String* self) {
return self->count;
}
List_String* Dictionary_String_keys(Dictionary_String* self) {
List_String* result = List_String_make();
for (int64_t spite_index = 0; spite_index < self->count; spite_index = spite_index + 1) { List_String_add(result, SpiteString_retain(self->keys[spite_index])); }
return result;
}
List_String* Dictionary_String_values(Dictionary_String* self) {
List_String* result = List_String_make();
for (int64_t spite_index = 0; spite_index < self->count; spite_index = spite_index + 1) { List_String_add(result, SpiteString_retain(self->values[spite_index])); }
return result;
}
